// Local simulation adapter: no fetch, persistence, production save or native bridge.
const clone=value=>JSON.parse(JSON.stringify(value));
function fail(zh,en){notify(T(zh,en),'error');return false;}
function addItem(id,n=1){if(!itemById(id))return;S.inventory[id]=(S.inventory[id]||0)+n;}
function changeStats(effect,multiplier=1){for(const [k,n] of Object.entries(effect))if(k in S.stats)S.stats[k]=Math.max(0,Math.min(cap(),Math.round(S.stats[k]+n*multiplier)));}
function progress(category,amount=1){for(const a of DATA.achievements)if(a.category===category)S.achievementProgress[a.id]=Math.min(a.target,(S.achievementProgress[a.id]||0)+amount);}
function activeCare(){return !S.sleeping&&!S.schedule||fail('伙伴现在在忙，等一会儿再来吧。','Your companion is busy. Try again when they are available.');}
function transaction(){const item=itemById(UI.selected),q=UI.quantity;if(!item||!Number.isInteger(q)||q<1)return fail('请先选择物品和有效数量。','Select an item and a valid quantity.');if(q>itemLimit(item))return fail('数量不足或超过本次上限。','Not enough items, or the quantity exceeds the limit.');if(UI.mode==='shop'){const cost=quote(item,q);if(!item.shop)return fail('这件物品不能直接购买。','This item cannot be purchased directly.');if(S.coins<cost)return fail('金币不足，可以去打工或兑换。','Not enough coins. Try work or a heart exchange.');S.coins-=cost;addItem(item.id,q);if(item.id==='bento')S.discountUsed=true;if(item.id==='emergency_biscuit')S.freeClaims+=q;progress('shop',q);render();notify(T('已'+(cost?'购买':'领取')+' '+itemText(item)+' ×'+q+'，放进背包了。',(cost?'Bought ':'Claimed ')+itemText(item)+' ×'+q+'. Added to your bag.'),'success');return true;}
 if(item.kind==='garden'){go('garden');return true;}if(!activeCare())return false;if((S.inventory[item.id]||0)<q)return fail('背包里没有足够的物品。','There are not enough items in your bag.');if(item.id==='golden_apple'&&!S.suppressAppleConfirm){confirmDialog(T('使用金苹果？','Use a golden apple?'),T('金苹果也用于梦想和传承。确认后使用 1 个，此份进度不再提示。','Golden apples also support dreams and legacy. Confirm to use one and suppress this prompt for this progress.'),'golden-apple-use');return false;}S.inventory[item.id]-=q;changeStats(effectiveItemEffects(item,q));if(item.id==='golden_apple'){changeStats(Object.fromEntries(STAT_DEFS.map(s=>[s[0],cap()])));S.hearts+=100;}if(item.id==='birthday_cake')S.hearts+=20;if(item.kind==='food')recordWish('feed');recordCare(item.kind==='food'?'feed':'item',q);recordItemUse(q);progress('care',q);progress('inventory',q);react(item.kind==='care'?'bath':item.kind==='food'?'eat':'happy',T('用掉 '+itemText(item)+' ×'+q+'。'+currentName()+' 很开心！','Used '+itemText(item)+' ×'+q+'. '+currentName()+' is delighted!'));render();return true;
}
function care(kind,confirmed=false){if(kind==='sleep'){if(S.schedule)return fail('日程结束后再休息吧。','Wait until the activity is over to sleep.');if(!S.sleeping&&!confirmed&&percent('cleanliness')<=25){confirmDialog(T('先洗干净再睡吗？','A wash before sleep?'),T('清洁偏低，直接睡觉会降低心情。取消后可以先清洁。','Low cleanliness makes sleep less pleasant and reduces mood. Cancel to wash first.'),'sleep-confirmed');return false;}S.sleeping=!S.sleeping;if(S.sleeping){recordWish('sleep');S.focus.running=false;if(percent('cleanliness')<=25)changeStats({mood:-12*cap()/100});}react(S.sleeping?'sleep':'happy',S.sleeping?T('晚安，我就在这里陪着你。','Good night. I’ll be right here.'):T('睡得好舒服！今天做点什么呢？','That was a good rest! What shall we do today?'));render();return true;}if(!activeCare())return false;if(kind==='play'){if(S.stats.energy<8)return fail('体力不足，先休息一下吧。','Not enough energy. Time for a rest.');changeStats({energy:-8,mood:(12+(UI.weather==='sunny'?5:0))*cap()/100,hunger:-3});}else changeStats({cleanliness:(25+(UI.weather==='rainy'?5:0)+(UI.season==='summer'?3:0))*cap()/100});recordCare(kind==='play'?'play':'clean');progress('care');react(kind==='play'?'happy':'bath',kind==='play'?T('一起玩了一会儿，心情亮起来了。','A little playtime makes the whole day brighter.'):T('洗得干干净净，闻起来香香的。','All clean and fresh. That feels lovely.'));render();return true;}
function performWork(){if(!activeCare())return false;const energy=workEnergy(),coins=workReward();if(S.stats.energy<energy||percent('hunger')<=10)return fail('先补充体力和饱腹，再来帮忙吧。','Restore some energy and hunger before helping out.');S.coins+=coins;recordCare('work');changeStats({energy:-energy,hunger:-5,mood:-3});if(S.cards.active==='friend')S.cards.workUsed=Math.min(80,S.cards.workUsed+8);UI.stack=[];react('work',T('便当准备好了，赚到 '+coins+' 金币！','Lunch boxes are ready. Earned '+coins+' coins!'));render();return true;}
function plant(tree){const p=S.garden[UI.plot],id=tree+'_sapling';if(!TREE_IDS.includes(tree)||p.state!=='empty')return fail('请选择空地再种植。','Choose an empty plot to plant.');if(!S.inventory[id])return fail('种苗不足，去商店补充吧。','No seedlings left. Visit the shop.');if(tree==='golden_apple_tree'&&S.garden.filter(p=>p.tree===tree).length>=3)return fail('金苹果树最多同时种植 3 棵。','At most three golden apple trees can grow at once.');S.inventory[id]--;recordItemUse();Object.assign(p,{state:'growing',tree,seconds:growthSeconds(tree),duration:growthSeconds(tree),harvests:0,watered:false,waterDay:0,fertilizerDay:0,nutrientDay:0,nutrient:false,fertilizer:null,careReduction:0,maxHarvests:maxHarvests(tree)});UI.stack=[];render();notify(T('种下一棵'+treeName(tree)+'，期待它慢慢长大。','Planted a '+treeName(tree)+'. Let’s watch it grow.'),'success');return true;}
function reduceGrowth(seconds){const p=S.garden[UI.plot];p.seconds=Math.max(10,p.seconds-seconds);p.careReduction=(p.careReduction||0)+seconds;}
function harvest(){const p=S.garden[UI.plot];if(p.state!=='ready')return fail('还没到收获的时候。','This plot is not ready to harvest.');const reward=p.tree==='fruit_tree'?{item:'apple',amount:3}:p.tree==='care_tree'?{item:'wet_wipes',amount:2}:p.tree==='gift_tree'?{item:'small_bouquet',amount:2}:p.tree==='money_tree'?{coins:360}:{item:'golden_apple',amount:1};const roll=(S.harvestTotal*37+17)%100,rare={fruit_tree:'strawberry_milk',care_tree:'medicine',gift_tree:'picture_book'}[p.tree];if(p.fertilizer==='heart_fertilizer'&&rare&&roll<20+S.gardenTools.fertilizer*5)reward.item=rare;if(reward.coins)S.coins+=reward.coins;else addItem(reward.item,reward.amount);const extraChance=(UI.weather==='cloudy'?5:0)+(UI.season==='autumn'?10:0)+(S.cards.active==='best'?20:0)+(p.fertilizer==='normal_fertilizer'?10+S.gardenTools.fertilizer*5:0);let extra='';if(S.cards.active==='best')S.cards.gardenUsed++;if(p.nutrient||roll<extraChance){if(reward.coins)S.coins+=reward.coins;else addItem(reward.item,reward.amount);extra=T(' 本轮额外收获一份！',' One extra harvest this cycle!');}p.harvests++;S.harvestTotal++;p.state=p.harvests>=(p.maxHarvests||maxHarvests(p.tree))?'withered':'growing';p.seconds=p.state==='growing'?growthSeconds(p.tree,true):0;p.duration=p.seconds;p.careReduction=0;p.watered=false;p.fertilizer=null;p.nutrient=false;progress('garden');render();notify(T('收获了 ','Harvested ')+(reward.coins?reward.coins+' '+T('金币','coins'):nameOf(reward.item)+' ×'+reward.amount)+extra,'success');return true;}
function startSchedule(index){const offer=scheduleOffers()[index];if(!offer)return false;if(S.schedule||S.schedulePending)return fail('请先完成当前日程和领奖。','Finish the current activity and claim its reward first.');if(S.completedOffers.includes(offer.id))return fail('这项日程今天已经完成。','This offer is already completed today.');if(!activeCare())return false;if(S.scheduleToday>=3)return fail('今天已完成三次日程，明天再继续。','Three activities completed today. Come back tomorrow.');if(S.stats.energy<offer.energy||percent('hunger')<=10||percent('health')<=40)return fail('状态不足，先休息或补充物品。','Restore your companion’s stats before starting.');changeStats({energy:-offer.energy,hunger:-offer.hunger,mood:-offer.mood});S.schedule={...offer,total:offer.minutes*60,remaining:offer.minutes*60};render();notify(T('开始了一个小日程，回来会带着收获。','A little activity has started. Rewards will be waiting afterward.'),'success');return true;}
function finishSchedule(){if(!S.schedule)return false;S.schedulePending={...S.schedule};S.schedule=null;notify(T('日程完成了！来选一份奖励吧。','Activity complete! Come and choose a reward.'),'success');return true;}
function claimSchedule(choice){const a=S.schedulePending;if(!a)return fail('这份日程奖励已经领取了。','This activity reward has already been claimed.');if(choice==='item'&&a.size===0)return fail('短日程只提供金币奖励。','Short activities offer the coin reward only.');const item={study:'picture_book',cooking:'bento',garden:'normal_fertilizer',exercise:'energy_drink'}[a.category];S.coins+=a.coins+(choice==='coins'?36:0);if(choice==='item')addItem(item,2);const skill=S.skills[a.category];skill.xp+=a.xp;skill.count++;while(skill.xp>=50&&skill.level<10){skill.xp-=50;skill.level++;}if(skill.level===10)skill.master++;S.scheduleToday++;if(a.id?.startsWith(S.day+':'))S.completedOffers.push(a.id);S.scheduleDone.push(a.category);const ticketBonus=S.scheduleToday>=3?resolveTicket('partner_schedule',100):'';S.schedulePending=null;progress('schedule');render();notify(T('日程奖励已收下，'+skillName(a.category)+'又进步了一点。','Rewards claimed. A little progress in '+skillName(a.category)+'.')+ticketBonus+(UI.edition==='bilibili'&&S.cloudReminder?T(' 记得保存云端进度。',' Remember to sync your progress.'):''),'success');return true;}
function finishFocus(){const f=S.focus;if(f.phase==='focus'){f.today++;const review=ensureReviewStats();review.focusCount++;review.focusMinutes+=f.focus;const reward=Math.round(24*(1+S.skills.study.level*.02))+(S.bonuses?.pomodoroCoinBonus||0);S.coins+=reward;progress('pomodoro');notify(T('专注完成，获得 '+reward+' 金币。休息一下吧。','Focus complete. Earned '+reward+' coins. Time for a break.'),'success');f.phase='rest';f.remaining=f.rest*60;}else {f.phase='focus';f.remaining=f.focus*60;if(f.round>=f.rounds){f.running=false;f.round=1;notify(T('今天这组专注完成了，辛苦啦。','Your set of focus rounds is complete. Nicely done.'),'success');}else f.round++;}}
function advanceSeconds(seconds){if(!Number.isFinite(seconds)||seconds<=0)return;const recoverEnergy=!S.schedule;S.simulatedSeconds=(S.simulatedSeconds||0)+seconds;for(const p of S.garden)if(p.state==='growing'){p.seconds=Math.max(0,p.seconds-seconds);if(p.seconds===0)p.state='ready';}if(S.schedule){S.schedule.remaining=Math.max(0,S.schedule.remaining-seconds);if(!S.schedule.remaining)finishSchedule();}let rest=seconds,guard=0;while(S.focus.running&&rest>0&&guard++<1000){const n=Math.min(rest,S.focus.remaining);S.focus.remaining-=n;rest-=n;if(S.focus.remaining<=0)finishFocus();}if(recoverEnergy){const interval=energyInterval(),before=Math.floor(((S.simulatedSeconds||0)-seconds)/interval),after=Math.floor(S.simulatedSeconds/interval);changeStats({energy:(after-before)*(S.sleeping?5:1)});}}
function nextDay(){advanceSeconds(86400);S.day++;S.ageDays++;ensureReviewStats().activeDays++;const memoryUnlocked=maybeUnlockMemory();S.wish=0;S.wishClaimed=false;S.wishKind=WISH_KINDS[(S.day-1)%WISH_KINDS.length];S.dailyTickets={processed:[],granted:[]};S.completedOffers=[];S.scheduleBoardCount=SKILLS.every(k=>S.skills[k].level>=6)?5:SKILLS.every(k=>S.skills[k].level>=3)?4:3;S.freeClaims=0;S.exchanges=0;S.discountUsed=false;S.scheduleToday=0;S.focus.today=0;S.neighborGifts=0;S.cards.claimed=false;S.cards.workUsed=0;S.cards.gardenUsed=0;for(const k of ['friendDays','bestDays'])S.cards[k]=Math.max(0,S.cards[k]-1);S.cards.active=S.cards.bestDays?'best':S.cards.friendDays?'friend':null;if(S.autoBackup&&S.day%S.backupDays===0)createBackup(T('自动备份','Automatic backup'));progress('daily');render();notify(T('演示时间来到第 '+S.day+' 天，每日额度已刷新。','Demo day '+S.day+'. Daily limits have refreshed.')+(memoryUnlocked?T(' 新的纪念插画已解锁，去纪念册看看吧。',' A new illustration is unlocked in your memory book.'):''),'success');}
function buyPass(kind){if(!['friend','best'].includes(kind))return false;const cost=kind==='best'?90:10,key=kind+'Days';if(kind==='friend'&&S.cards.active==='best')return fail('挚友卡生效期间无法购买好友卡。','A best friend pass is already active.');if(S.cards[key]>=90)return fail('续期最多累积 90 天。','Pass validity is capped at 90 days.');if(S.hearts<cost)return fail('小心心不足，暂时无法购买。','Not enough hearts for this pass.');S.hearts-=cost;S.cards[key]=Math.min(90,S.cards[key]+30);S.cards.active=kind;render();notify(T('搭子卡已生效，剩余 '+S.cards[key]+' 天。','Pass activated for '+S.cards[key]+' more days.'),'success');return true;}
function draw(n){if(![1,10].includes(n)||S.gacha.drawing)return false;const machine=UI.machine,payment=UI.payment,available=machine==='heart'?(S.inventory.golden_apple||0):payment==='tickets'?S.tickets:S.coins,cost=machine==='heart'||payment==='tickets'?n:n*500;if(available<cost)return fail('余额不足，请先补充金币、扭蛋券或金苹果。','Not enough coins, tickets or golden apples.');if(machine==='heart')S.inventory.golden_apple-=cost;else if(payment==='tickets')S.tickets-=cost;else S.coins-=cost;const pool=machine==='heart'?DATA.heartPool:DATA.pool,total=pool.reduce((sum,r)=>sum+r.weight,0),results=[];for(let i=0;i<n;i++){let roll=Math.random()*total,r=pool[pool.length-1];for(const entry of pool){roll-=entry.weight;if(roll<0){r=entry;break;}}r={...r};if(machine==='apple'){S.gacha.pity++;if(S.gacha.pity>=1000)r={...DATA.pool.find(x=>x.rarity==='jackpot')};if(r.rarity==='jackpot')S.gacha.pity=0;}results.push(r);}if(machine==='heart'&&n===10){const sum=results.reduce((v,r)=>v+r.amount,0);if(sum<100)results[results.length-1].amount+=100-sum;}S.gacha.pending={machine,results};S.gacha.drawing=true;S.gacha.results=[];UI.stack=[];render();notify(T('咕噜咕噜，小惊喜正在路上。','Round and round, a little surprise is on its way.'));gachaTimer=setTimeout(settleDraw,1700);return true;}
function settleDraw(){clearTimeout(gachaTimer);const pending=S.gacha.pending;if(!pending)return false;S.gacha.pending=null;S.gacha.drawing=false;S.gacha.results=pending.results;for(const r of pending.results){if(r.kind==='coins')S.coins+=r.amount;else if(r.kind==='hearts')S.hearts+=r.amount;else addItem(r.item,r.amount);}S.gacha.total+=pending.results.length;S.gacha.history.unshift({...pending,time:T('演示第 '+S.day+' 天','Demo day '+S.day)});S.gacha.history=S.gacha.history.slice(0,30);render();notify(T('抽到 '+pending.results.length+' 份惊喜，已经全部收好了。',pending.results.length+' surprises, all added to your wallet and bag.'),'success');return true;}
function claimAchievement(id,quiet=false){const a=DATA.achievements.find(x=>x.id===id);if(!a||S.achievementClaimed.includes(id)||!achievementComplete(a))return quiet?false:fail('还未达成，或奖励已经领取。','Not yet complete, or the reward has already been claimed.');S.achievementClaimed.push(id);S.coins+=a.coins;S.hearts+=a.hearts;if(a.item)addItem(a.item,a.amount);if(a.effect){S.bonuses??={};S.bonuses[a.effect[0]]=(S.bonuses[a.effect[0]]||0)+Number(a.effect[1]);}if(!quiet){render();notify(T('收下了「'+a[UI.lang].title+'」的奖励。','Claimed the reward for “'+a[UI.lang].title+'”.'),'success');}return true;}
function invest(arg){const [k,raw]=arg.split(':'),d=S.dreams[k];if(!d||d.stage>=5)return false;if(!dreamRequirements(k).every(r=>r.ok))return fail('等级或日程条件尚未满足。','The level or activity requirements are not yet met.');const remaining=STAGE_COSTS[d.stage]-d.invested,n=raw==='rest'?remaining:Math.min(remaining,Number(raw));if(!Number.isFinite(n)||n<=0)return false;if(S.coins<n)return fail('金币不足，可选更小一档投入。','Not enough coins. Try a smaller contribution.');S.coins-=n;d.invested+=n;render();notify(T('为梦想投入 '+n+' 金币，离下一步更近了。','Contributed '+n+' coins. One step closer to your dream.'),'success');return true;}
function completeDream(k){const d=S.dreams[k];if(!d||d.stage>=5)return fail('这个梦想已经完成。','This dream is already complete.');if(!dreamRequirements(k).every(r=>r.ok)||d.invested<STAGE_COSTS[d.stage]||S.inventory.golden_apple<APPLE_COSTS[d.stage])return fail('投入、金苹果或阶段条件还未满足。','Contributions, apples or stage requirements are still missing.');S.inventory.golden_apple-=APPLE_COSTS[d.stage];d.stage++;d.invested=0;render();notify(T('「'+DATA.copy[UI.lang].dreams[k].title+'」完成第 '+d.stage+' 阶段！','“'+DATA.copy[UI.lang].dreams[k].title+'” stage '+d.stage+' complete!'),'success');return true;}
function eventGift(kind){const defs={birthday:{title:T('生日快乐！','Happy birthday!'),coins:100,hearts:20,item:'birthday_cake'},festival:{title:T('收下一份节日心意','A little festival gift'),coins:128,item:'strawberry_cake',amount:2},anniversary:{title:T('又陪你走过了一年','Another year together'),coins:365,hearts:36,item:'golden_apple'},help:{title:T('给初来小窝的你','A welcome to your little home'),coins:60,item:'bento',amount:2},announcement:{title:T('小窝焕新公告','A refreshed little home'),subtitle:T('格子背包，四季小窝','A grid bag and a home for every season'),text:T('通知移到了屏幕顶部，更多小日常等你慢慢发现。','Messages now appear at the top of the screen. There are more little moments to discover.'),coins:120,item:'normal_fertilizer'},return:{title:T('欢迎回家','Welcome home'),text:T('重新摸摸伙伴之后，小目标就完成了。','Pet your companion again to complete your little return goal.'),coins:88,item:'bento',amount:3}};const gift=defs[kind];openModal('reward',{...gift,id:['help','announcement'].includes(kind)?kind:kind+'-'+S.day});}
function claimEvent(){const m=UI.stack.at(-1);if(m?.type!=='reward')return false;const data=m.data;if(S.claimed.includes(data.id))return fail('这份礼物已经收下啦。','You have already received this gift.');if(data.id.startsWith('return-')&&!S.returnDone)return fail('先回到小窝摸摸伙伴，完成回归小目标。','Pet your companion at home to complete your return goal.');S.claimed.push(data.id);S.coins+=data.coins||0;S.hearts+=data.hearts||0;if(data.item)addItem(data.item,data.amount||1);if(data.id.startsWith('return-'))S.returning=false;closeModal();notify(T('礼物已收进背包，今天也要开心。','The gift is in your bag. Have a lovely day.'),'success');return true;}
function exportDemo(){if(S.gacha.drawing)settleDraw();const state=clone(S);state.backups=[];state.cloud=null;delete state.importRollback;delete state.gacha.pending;state.gacha.drawing=false;state.focus.running=false;return {format:'pocket-ui-prototype-v2',version:1,state};}
function snapshot(label){return {label:label+' · '+T('第 '+S.day+' 天','Day '+S.day),role:currentName(),level:S.level,coins:S.coins,data:exportDemo()};}
function createBackup(label=T('手动备份','Manual backup')){if(S.gacha.drawing)settleDraw();S.backups.unshift(snapshot(label));S.backups=S.backups.slice(0,8);return true;}
function restoreData(data){if(!data||data.format!=='pocket-ui-prototype-v2'||!data.state)return fail('不是有效的原型演示文件。','This is not a valid prototype demo file.');const backups=S.backups,cloud=S.cloud;clearTimeout(gachaTimer);clearTimeout(poseTimer);clearTimeout(updateTimer);S={...seedState(data.state.preset),...clone(data.state)};ensureReviewStats();S.unlockedCgIds=Array.isArray(S.unlockedCgIds)?S.unlockedCgIds:[];S.backups=backups;S.cloud=cloud;S.gacha.drawing=false;delete S.gacha.pending;UI.stack=[];UI.pose='idle';go('home');notify(T('演示进度已恢复，配色与环境保持。','Demo progress restored. Your colors and environment are kept.'),'success');return true;}
function resetProgress(preset){clearTimeout(gachaTimer);clearTimeout(poseTimer);clearTimeout(updateTimer);S=seedState(preset);UI.stack=[];UI.pose='idle';UI.quantity=1;UI.plot=0;createBackup(T('初始演示快照','Initial demo snapshot'));go('home');notify(T('已切换到示例进度，外观与环境保持。','Demo progress changed. Appearance and environment are kept.'),'success');}
function downloadText(filename,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copyText(text,selectId){try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(text);notify(T('已复制到剪贴板。','Copied to the clipboard.'),'success');}catch{if(selectId){$(selectId)?.focus();$(selectId)?.select();notify(T('浏览器未开放剪贴板，文本已选中，请按 Ctrl+C 复制。','Clipboard access is unavailable. Text selected; press Ctrl+C to copy.'));}else openModal('copy-text',{text});}}
function shareText(year=false){return T('我和 '+currentName()+' 已经相伴 '+S.ageDays+' 天啦！等级 '+S.level+'，一起收获了 '+S.harvestTotal+' 次果实。','I’ve spent '+S.ageDays+' days with '+currentName()+'! Level '+S.level+', with '+S.harvestTotal+' garden harvests together.')+(year?T(' 这是我们的年度回顾。',' This is our year together.'): ' #Pocket');}
async function downloadCard(kind){if(kind==='year')return downloadYearReview();const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1100;const ctx=canvas.getContext('2d'),p={paper:'#fff3e3',surface:'#fffdf8',ink:'#28364a','accent-text':'#755549',muted:'#596b7f'};ctx.fillStyle=p.paper;ctx.fillRect(0,0,900,1100);ctx.fillStyle=p.surface;ctx.fillRect(40,40,820,1020);ctx.fillStyle='#fbdce6';ctx.fillRect(666,40,194,112);ctx.fillStyle='#dceafa';ctx.fillRect(40,948,164,112);ctx.fillStyle='#e8dffa';ctx.fillRect(737,948,123,112);ctx.save();ctx.translate(768,62);ctx.rotate(.12);ctx.fillStyle='#ffdf86';ctx.fillRect(-52,-9,104,18);ctx.restore();ctx.textAlign='center';ctx.fillStyle=p['accent-text'];ctx.font='24px "Microsoft YaHei",sans-serif';ctx.fillText('POCKET · A LITTLE LIFE, TOGETHER',450,112);ctx.fillStyle=p.ink;ctx.font='bold 42px "Microsoft YaHei",sans-serif';ctx.fillText(kind==='year'?T('一起走过的这一年','Our year together'):kind==='gacha'?T('今天的小惊喜','Today’s little surprises'):currentName()+T(' 的伙伴名片','’s companion card'),450,190);if(kind==='gacha'){for(let i=0;i<S.gacha.results.length;i++){const r=S.gacha.results[i],x=150+(i%3)*300,y=290+Math.floor(i/3)*160;ctx.font='20px "Microsoft YaHei",sans-serif';ctx.fillStyle=p['accent-text'];ctx.fillText(rarityLabel(r.rarity),x,y);ctx.fillStyle=p.ink;const words=rewardText(r).replace(/&amp;/g,'&').replace(/&#39;/g,"'");ctx.fillText(words,x,y+45,260);}}else {await new Promise(resolve=>{const art=new Image();art.onload=()=>{const scale=Math.min(440/art.width,510/art.height);ctx.drawImage(art,450-art.width*scale/2,250,art.width*scale,art.height*scale);resolve();};art.onerror=resolve;art.src=ASSETS[(ROLES.includes(S.role)?S.role:'furo')+'_happy'];});ctx.font='26px "Microsoft YaHei",sans-serif';ctx.fillText(T('相伴 '+S.ageDays+' 天 · Lv.'+S.level,'Together for '+S.ageDays+' days · Lv.'+S.level),450,855);ctx.fillText(T('照顾 '+S.totalCare+' 次 · 花园收获 '+S.harvestTotal+' 次',S.totalCare+' care moments · '+S.harvestTotal+' harvests'),450,905);}ctx.fillStyle=p.muted;ctx.font='19px "Microsoft YaHei",sans-serif';ctx.fillText(T('一只小伙伴，一段慢慢长大的时光。','A little companion, a life growing together.'),450,1020);const a=document.createElement('a');a.download='Pocket-'+kind+'-demo.png';a.href=canvas.toDataURL('image/png');a.click();notify(T('图片已生成，已请求浏览器下载。','Image created. Download requested.'),'success');}
