 advance:arg=>{if(arg==='day')return nextDay();if(arg==='schedule'){if(!S.schedule)return fail('还没有进行中的日程。','There is no activity in progress.');advanceSeconds(S.schedule.remaining);}else if(arg==='focus'){const was=S.focus.running;S.focus.running=true;advanceSeconds(S.focus.remaining);if(!was)S.focus.running=false;}else advanceSeconds(Number(arg));render();notify(T('模拟时间已推进，相关状态已更新。','Simulated time advanced. Related states have updated.'),'success');},
