Object.assign(ACTIONS,EXTRA_ACTIONS);
function dispatch(action,arg=''){if(!Object.hasOwn(ACTIONS,action))throw new Error('Unknown prototype action: '+action);return ACTIONS[action](arg);}
function playSound(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;const ctx=new Audio(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);osc.frequency.value=660;gain.gain.setValueAtTime(.025,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.16);osc.start();osc.stop(ctx.currentTime+.16);osc.onended=()=>ctx.close();}catch{}}
function changeSetting(kind,value){switch(kind){case 'wish-kind':if(WISH_KINDS.includes(value)){S.wishKind=value;S.wish=0;S.wishClaimed=false;}break;case 'return-kind':if(['touch','feed','clean','sleep'].includes(value)){S.returnKind=value;S.returnDone=false;}break;case 'recovery-index':UI.recoveryIndex=Math.max(0,Math.min(S.backups.length-1,Number(value)||0));break;case 'quantity':{const item=itemById(UI.selected);UI.quantity=Math.floor(Number(value)||1);if(item)normalizeQuantity(item);break;}case 'name':if(UI.edition==='bilibili')return;if(!value.trim())return fail('名字不能为空。','A name is required.');S.names[S.role]=value.trim().slice(0,20);notify(T('已经记住这个名字啦。','I’ll remember this name.'),'success');break;case 'birthday':if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return fail('请选择有效生日。','Choose a valid birthday.');S.birthday=value.slice(5);break;case 'language':UI.lang=value==='en'?'en':'zh';S.lastEvent=T('晃了晃脑袋，正在等你叫它。','A little head tilt, waiting for you.');break;case 'edition':UI.edition=value==='bilibili'?'bilibili':'standard';if(UI.edition==='bilibili'&&!ROLES.includes(S.role)){S.role='furo';S.mods.forEach(m=>m.enabled=false);}break;case 'focus-length':case 'rest-length':case 'focus-rounds':{const key={'focus-length':'focus','rest-length':'rest','focus-rounds':'rounds'}[kind],min=1,max=key==='focus'?180:key==='rest'?60:8,n=Math.max(min,Math.min(max,Math.floor(Number(value)||min)));S.focus[key]=n;S.focus.running=false;S.focus.remaining=S.focus[S.focus.phase]*60;S.focus.round=Math.min(S.focus.round,S.focus.rounds);break;}case 'backup-days':S.backupDays=Math.max(1,Math.min(30,Math.floor(Number(value)||1)));break;case 'backup-target':S.backupTarget=value.trim().replace(/[<>:"/\\|?*]/g,'').slice(0,80)||'Pocket-demo.json';break;case 'update-preview':UI.updatePreview=['available','latest','error'].includes(value)?value:'available';break;}render();}
function inputValue(kind,value){if(kind==='backup-candidate'){UI.backupCandidate=value;return;}if(kind==='import-demo-text'){UI.importText=value;return;}if(kind==='search'){UI.query=value;render();}else if(kind==='achievement-search'){UI.achievementQuery=value;render();}else if(kind==='color-picker'||kind==='color-hex'){const valid=/^#[0-9a-f]{6}$/i.test(value);UI.customError=!valid;const error=$('color-error'),hex=$('color-hex');if(error)error.hidden=valid;if(hex)hex.setAttribute('aria-invalid',String(!valid));if(valid){UI.color=value.toLowerCase();UI.theme='custom';applyTheme();const label=document.querySelector('.color-row .pill');if(label)label.innerHTML=I('palette')+T('自定义','Custom');if(kind==='color-picker'&&hex)hex.value=value.toUpperCase();if(kind==='color-hex'&&$('color-picker'))$('color-picker').value=value;document.querySelectorAll('.theme-choice>.icon').forEach(el=>el.remove());document.querySelectorAll('[data-act="theme"]').forEach(el=>{el.classList.remove('active');el.setAttribute('aria-pressed','false');});}}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-act]');if(button&&!button.disabled&&!button.closest('[inert]')){const result=dispatch(button.dataset.act,button.dataset.arg||'');if(result?.catch)result.catch(error=>{console.error(error);fail('操作未完成，请重试。','The action could not finish. Please try again.');});}else if(event.target.classList.contains('layer')&&Number(event.target.dataset.layer)===UI.stack.length-1)closeModal();});
document.addEventListener('change',event=>{if(event.target.dataset.file==='demo-save'){const file=event.target.files?.[0];if(file)file.text().then(text=>stageDemoImport(text,file.name)).catch(()=>fail('文件读取失败。','File could not be read.'));return;}if(event.target.dataset.change)changeSetting(event.target.dataset.change,event.target.value);});
document.addEventListener('input',event=>{if(event.target.dataset.input)inputValue(event.target.dataset.input,event.target.value);});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(UI.stack.length)closeModal();else if(UI.notice)dispatch('dismiss-notice');return;}if(event.key!=='Tab'||!UI.stack.length)return;const panel=document.querySelector('.layer:last-child .panel'),focusable=[...panel.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]')].filter(el=>!el.hidden);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1),active=document.activeElement;if(event.shiftKey&&(active===first||!panel.contains(active))){last.focus();event.preventDefault();}else if(!event.shiftKey&&(active===last||!panel.contains(active))){first.focus();event.preventDefault();}});
createBackup(T('初始演示快照','Initial demo snapshot'));
render();
let previousTick=Date.now();
timerHandle=setInterval(()=>{const now=Date.now(),elapsed=Math.floor((now-previousTick)/1000);if(elapsed<1)return;previousTick+=elapsed*1000;const video=UI.stack.at(-1);if(video?.type==='video'&&video.data.playing){video.data.elapsed=(video.data.elapsed||0)+elapsed;if(video.data.elapsed>=4){video.data.elapsed=0;video.data.frame=((video.data.frame||0)+1)%3;render();}}const beforeSchedule=!!S.schedule,beforeReady=S.garden.filter(p=>p.state==='ready').length,phase=S.focus.phase;advanceSeconds(elapsed);if(beforeSchedule!==!!S.schedule||beforeReady!==S.garden.filter(p=>p.state==='ready').length||phase!==S.focus.phase){render();return;}if($('energy-hint'))$('energy-hint').textContent=energyHint();if(S.focus.running&&$('focus-time'))$('focus-time').textContent=timeText(S.focus.remaining);if(S.schedule){const el=document.querySelector('.countdown');if(el)el.textContent=timeText(S.schedule.remaining);}},1000);
